        }

        if (endCode > 0 && endCode < firstCode ||
                endCode > 0x0010FFFF ||
                endCode >= 0x0000D800 && endCode <= 0x0000DFFF) {
            throw new IOException("Invalid characters codes");
        }

        for (long j = 0; j <= endCode - firstCode; ++j) {
            long glyphIndex = startGlyph + j;
