import org.ofdrw.converter.font.*;
import java.io.*;
import java.util.*;

public class Proto {

    // ---------- generic helpers ----------
    static byte[] u16(int v) { return new byte[]{(byte)(v>>8), (byte)v}; }
    static byte[] u32(long v) { return new byte[]{(byte)(v>>24),(byte)(v>>16),(byte)(v>>8),(byte)v}; }

    static byte[] index(byte[]... items) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write((byte)(items.length >> 8)); out.write((byte)items.length);
        if (items.length == 0) return out.toByteArray();
        int offSize = 4;
        out.write(offSize);
        int off = 1;
        byte[][] offs = new byte[items.length + 1][];
        long cur = 1;
        for (int i = 0; i <= items.length; i++) {
            byte[] b = new byte[4];
            b[0]=(byte)(cur>>24); b[1]=(byte)(cur>>16); b[2]=(byte)(cur>>8); b[3]=(byte)cur;
            out.write(b, 0, 4);
            if (i < items.length) cur += items[i].length;
        }
        for (byte[] it : items) out.write(it, 0, it.length);
        return out.toByteArray();
