import org.ofdrw.converter.font.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Proto2 {

    static byte[] u16(int v) { return new byte[]{(byte)(v>>8), (byte)v}; }
    static byte[] u32(long v) { return new byte[]{(byte)(v>>24),(byte)(v>>16),(byte)(v>>8),(byte)v}; }

    static byte[] cat(byte[]... parts) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (byte[] p : parts) out.write(p, 0, p.length);
        return out.toByteArray();
    }

    static byte[] buildTtf(Map<String, byte[]> tables) {
        List<String> tags = new ArrayList<>(tables.keySet());
        Collections.sort(tags);
        int n = tags.size();
        int entrySelector = 0;
        while ((1 << (entrySelector + 1)) <= n) entrySelector++;
        int searchRange = (1 << entrySelector) * 16;
        int rangeShift = n * 16 - searchRange;
        ByteArrayOutputStream body = new ByteArrayOutputStream();
        int dirSize = 12 + n * 16;
        int[] offsets = new int[n];
        int cur = dirSize;
        for (int i = 0; i < n; i++) {
            cur = (cur + 3) & ~3;
            offsets[i] = cur;
            cur += tables.get(tags.get(i)).length;
        }
        byte[] out = new byte[cur];
        int p = 0;
        System.arraycopy(u32(0x00010000L), 0, out, 0, 4); p = 4;
        System.arraycopy(u16(n), 0, out, p, 2); p += 2;
        System.arraycopy(u16(searchRange), 0, out, p, 2); p += 2;
        System.arraycopy(u16(entrySelector), 0, out, p, 2); p += 2;
        System.arraycopy(u16(rangeShift), 0, out, p, 2); p += 2;
        for (int i = 0; i < n; i++) {
            byte[] tag = tags.get(i).getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            System.arraycopy(tag, 0, out, p, 4); p += 4;
            System.arraycopy(u32(0), 0, out, p, 4); p += 4;
            System.arraycopy(u32(offsets[i]), 0, out, p, 4); p += 4;
            System.arraycopy(u32(tables.get(tags.get(i)).length), 0, out, p, 4); p += 4;
        }
        for (int i = 0; i < n; i++) {
            byte[] d = tables.get(tags.get(i));
            System.arraycopy(d, 0, out, offsets[i], d.length);
        }
        return out;
    }

    static byte[] head(int unitsPerEm, int indexToLocFormat) {
        byte[] b = new byte[54];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);
        System.arraycopy(u32(0x00010000L), 0, b, 4, 4);
        System.arraycopy(u32(0x5F0F3CF5L), 0, b, 12, 4);
        System.arraycopy(u16(unitsPerEm), 0, b, 18, 2);
        System.arraycopy(u16(1000), 0, b, 50, 2);
        if (indexToLocFormat != 0) { b[50]=(byte)0; b[51]=(byte)1; }
        return b;
    }
    static byte[] head(int unitsPerEm, int indexToLocFormat, boolean ignored) {
        byte[] b = head(unitsPerEm, 0);
        b[50] = (byte)(indexToLocFormat >> 8); b[51] = (byte)indexToLocFormat;
        return b;
    }

    static byte[] maxp(int numGlyphs) {
        byte[] b = new byte[32];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);
        System.arraycopy(u16(numGlyphs), 0, b, 4, 2);
        return b;
    }

    static byte[] hhea(int numberOfHMetrics) {
        byte[] b = new byte[36];
        System.arraycopy(u32(0x00010000L), 0, b, 0, 4);
        System.arraycopy(u16(numberOfHMetrics), 0, b, 34, 2);
        return b;
    }

    static byte[] simpleGlyphOnePoint(int xMin, int yMin, int xMax, int yMax) {
        return cat(u16(1), u16(xMin), u16(yMin), u16(xMax), u16(yMax), u16(0), u16(0), new byte[]{0}, u16(0), u16(0));
    }

    static byte[] cff() {
        return new byte[]{1, 0, 4, 4, 0, 1, 4, 0, 0, 0, 1, 0, 0, 0, 5, 84, 101, 115, 116, 0, 1, 4, 0, 0, 0, 1, 0, 0, 0, 18, 29, 0, 0, 0, 51, 17, 29, 0, 0, 0, 0, 29, 0, 0, 0, 63, 18, 0, 0, 0, 0, 0, 1, 4, 0, 0, 0, 1, 0, 0, 0, 2, 14};
    }

    static byte[] cmap6(int firstCode, int[] gids) {
        ByteArrayOutputStream sub = new ByteArrayOutputStream();
        sub.write(0); sub.write(6);
        int len = 10 + gids.length * 2;
        sub.write(0); sub.write(len);
        sub.write(0); sub.write(0);
        sub.write(firstCode >> 8); sub.write(firstCode);
        sub.write(gids.length >> 8); sub.write(gids.length);
        for (int g : gids) { sub.write(g >> 8); sub.write(g); }
        byte[] subData = sub.toByteArray();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(0); out.write(0);   // version
        out.write(0); out.write(1);   // numTables
        out.write(0); out.write(3);   // platform windows
        out.write(0); out.write(1);   // unicode bmp
        out.write(0); out.write(0); out.write(0); out.write(12);
        try { out.write(subData); } catch (IOException e) { throw new UncheckedIOException(e); }
        return out.toByteArray();
    }

    static byte[] name(String family, String subFamily, String ps) {
        String[] strings = {family, subFamily, ps};
        int[] ids = {1, 2, 6};
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(0); out.write(0);
        out.write(0); out.write(strings.length);
        int strOff = 6 + 12 * strings.length;
        out.write(strOff >> 8); out.write(strOff);
        int off = 0;
        for (int i = 0; i < strings.length; i++) {
            byte[] b = strings[i].getBytes(java.nio.charset.StandardCharsets.US_ASCII);
            out.write(0); out.write(1);  // macintosh
            out.write(0); out.write(0);  // roman
            out.write(0); out.write(0);  // english
            out.write(0); out.write(ids[i]);
            out.write(b.length >> 8); out.write(b.length);
            out.write(off >> 8); out.write(off);
            off += b.length;
        }
        for (String s : strings) {
            byte[] b = s.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
            try { out.write(b); } catch (IOException e) { throw new UncheckedIOException(e); }
        }
        return out.toByteArray();
    }

    static TrueTypeFont parse(byte[] data) throws IOException {
        return new TrueTypeFont().parse(new MemoryTTFDataStream(data));
    }

    public static void main(String[] args) throws Exception {
        // 1. minimal short loca
        byte[] glyph = simpleGlyphOnePoint(0, 0, 100, 100);
        Map<String, byte[]> t = new LinkedHashMap<>();
        t.put("head", head(1000, 0, true));
        t.put("maxp", maxp(2));
        byte[] locaShort = cat(u16(0), u16(0), u16((glyph.length + 1) / 2));
        t.put("loca", locaShort);
        t.put("glyf", glyph);
        t.put("cmap", cmap6(0x41, new int[]{1, 0}));
        t.put("name", name("ProtoFamily", "Regular", "ProtoFamily-Regular"));
        byte[] ttf = buildTtf(t);
        TrueTypeFont f = parse(ttf);
        System.out.println("1 matrix=" + f.getFontMatrix());
        System.out.println("  family=" + f.fontFamily + " sub=" + f.fontSubFamily + " ps=" + f.psName);
        System.out.println("  glyph0=" + f.getGlyph(0) + " glyph1=" + f.getGlyph(1) + " glyph2=" + f.getGlyph(2) + " g-1=" + f.getGlyph(-1));
        System.out.println("  gid(0x41)=" + f.getUnicodeCmapLookup().getGlyphId(0x41));
        System.out.println("  unicodeGlyph=" + f.getUnicodeGlyph(0x41));
        System.out.println("  glyph1 x0=" + f.getGlyph(1).getDescription().getXCoordinate(0));
        System.out.println("  path1=" + f.getPath(1));

        // 2. long loca
        Map<String, byte[]> t2 = new LinkedHashMap<>(t);
        t2.put("head", head(2048, 1, true));
        t2.put("loca", cat(u32(0), u32(0), u32(glyph.length)));
        TrueTypeFont f2 = parse(buildTtf(t2));
        System.out.println("2 matrix=" + f2.getFontMatrix() + " x0=" + f2.getGlyph(1).getDescription().getXCoordinate(0));

        // 3. hhea/hmtx lsb
        Map<String, byte[]> t3 = new LinkedHashMap<>(t);
        t3.put("hhea", hhea(2));
        t3.put("hmtx", cat(u16(500), u16(0), u16(500), u16(-150)));
        TrueTypeFont f3 = parse(buildTtf(t3));
        System.out.println("3 x0=" + f3.getGlyph(1).getDescription().getXCoordinate(0));

        // 4. CFF table branch
        Map<String, byte[]> t4 = new LinkedHashMap<>();
        t4.put("head", head(1000, 0, true));
        t4.put("CFF ", cff());
        t4.put("maxp", maxp(1));
        t4.put("name", name("CffFamily", "Bold", "CffFamily-Bold"));
        TrueTypeFont f4 = parse(buildTtf(t4));
        System.out.println("4 family=" + f4.fontFamily + " sub=" + f4.fontSubFamily + " ps=" + f4.psName);
        System.out.println("  matrix=" + f4.getFontMatrix());
        System.out.println("  glyph0=" + f4.getGlyph(0) + " glyph1=" + f4.getGlyph(1));
        System.out.println("  path0=" + f4.getPath(0));

        // 5. CFF table with empty cff -> fallback
        Map<String, byte[]> t5 = new LinkedHashMap<>(t);
        t5.put("CFF ", new byte[]{1, 0, 4, 4, 0, 0, 0, 0, 0, 0, 0, 0});
        TrueTypeFont f5 = parse(buildTtf(t5));
