    void parseTrueTypeFont_readsCmapTable() throws IOException {
        byte[] glyph = oneContourGlyph();
        Map<String, byte[]> tables = minimalTableSet(1000, 0);
        tables.put("loca", cat(u16(0), u16(0), u16((glyph.length + 1) / 2)));
        tables.put("glyf", glyph);
        // 'A' -> gid 1, 'B' -> gid 0
        tables.put("cmap", cmapFormat6(0x41, new int[]{1, 0}));

        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(tables)));

        assertNotNull(font.getSubtable(3, 1), "应解析出 Windows/Unicode BMP 子表");
        assertEquals(1, font.getUnicodeCmapLookup().getGlyphId('A'));
        GlyphData glyphA = font.getUnicodeGlyph('A');
        assertNotNull(glyphA);
        assertEquals(1, glyphA.getNumberOfContours());
