    @Test
    @DisplayName("解析 name 表填充 fontFamily/fontSubFamily/psName")
    void parseTrueTypeFont_readsNamingTable() throws IOException {
        Map<String, byte[]> tables = minimalTableSet(1000, 0);
        tables.put("name", nameTable("OfdTestFamily", "Regular", "OfdTestFamily-Regular"));

        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(tables)));

        assertEquals("OfdTestFamily", font.fontFamily);
        assertEquals("Regular", font.fontSubFamily);
        assertEquals("OfdTestFamily-Regular", font.psName);
    }

    @Test
    @DisplayName("没有 cmap 表时 Unicode 查找抛出 IllegalArgumentException，Unicode 字形退化为 gid 0")
    void parseTrueTypeFont_withoutCmapTable() throws IOException {
        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(minimalTableSet(1000, 0))));

        assertNull(font.getSubtable(3, 1));
