        PathPoint out = result.get(0);
        assertMm("radii keep their own value", 5d, out.rx);
        assertMm("radii keep their own value", 6d, out.ry);
        assertMm("end point is scaled", 80d, out.x);
        assertMm("end point is scaled", 100d, out.y);
    }

    @Test
    @DisplayName("Arc end point is flipped when the origin is fixed to the PDF corner")
    void testArcEndPointIsFlipped() {
        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(new PathPoint("A", 5f, 6f, 45f, 1f, 1f, 40f, 50f)),
                false, null, null, null, true, 1d);

        PathPoint out = result.get(0);
        assertMm("end point x", 40d, out.x);
        assertMm("end point y flipped", PAGE_HEIGHT - 50d, out.y);
        assertEquals(45f, out.rotation);
    }

    @Test
    @DisplayName("The composite object boundary offset is applied on top of the adjusted coordinate")
    void testCompositeObjectBoundaryOffset() {
        ST_Box compositeBoundary = new ST_Box(2d, 3d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, compositeBoundary, null, false, 1d);

        assertMm("x = point x + composite boundary x", 12d, result.get(0).x1);
        assertMm("y = point y + composite boundary y", 23d, result.get(0).y1);
    }

    @Test
    @DisplayName("The composite object boundary offset is included in the origin fix")
    void testCompositeObjectBoundaryWithOriginFix() {
        ST_Box compositeBoundary = new ST_Box(2d, 3d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, compositeBoundary, null, true, 1d);

        assertMm("x = point x + composite boundary x", 12d, result.get(0).x1);
        assertMm("y is flipped after all offsets", PAGE_HEIGHT - 23d, result.get(0).y1);
    }

    @Test
    @DisplayName("The composite object CTM is applied before the composite object boundary")
    void testCompositeObjectCtmIsApplied() {
        ST_Array compositeCtm = new ST_Array(1d, 0d, 0d, 1d, 5d, 7d);
        ST_Box compositeBoundary = new ST_Box(1d, 1d, 50d, 50d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(0f, 0f)), false, null, compositeBoundary, compositeCtm, false, 1d);

        // (0,0) -> composite ctm -> (5,7) -> composite boundary -> (6,8)
        assertMm("x after composite ctm and boundary", 6d, result.get(0).x1);
        assertMm("y after composite ctm and boundary", 8d, result.get(0).y1);
    }

    @Test
    @DisplayName("A composite object CTM alone has no effect without a composite object boundary")
    void testCompositeObjectCtmWithoutBoundaryIsIgnored() {
        ST_Array compositeCtm = new ST_Array(1d, 0d, 0d, 1d, 100d, 100d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move(10f, 20f)), false, null, null, compositeCtm, false, 1d);

        assertMm("x ignores the composite CTM", 10d, result.get(0).x1);
        assertMm("y ignores the composite CTM", 20d, result.get(0).y1);
    }

    @Test
    @DisplayName("Unknown operators are dropped")
    void testUnknownOperatorIsDropped() {
        PathPoint unknown = new PathPoint("Z", 10f, 20f, 0, 0, 0, 0);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(unknown, move(1f, 2f)), false, null, null, null, false, 1d);

        assertEquals(1, result.size(), "only the supported operator is returned");
        assertEquals("M", result.get(0).type);
        assertMm("supported point is still converted", 1d, result.get(0).x1);
        assertEquals(10f, unknown.x1, "dropped operators are not modified");
    }

    @Test
    @DisplayName("Move/line points are converted in place and the very same instances are returned")
    void testMovePointsAreMutatedInPlace() {
        PathPoint m = move(10f, 20f);
        List<PathPoint> input = listOf(m);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                input, false, null, null, null, false, 1d);

        assertSame(m, result.get(0), "M/L/C/S points are returned as the same instance");
        assertMm("the input instance carries the converted x", 10d, m.x1);
        assertMm("the input instance carries the converted y", 20d, m.y1);
    }

    @Test
    @DisplayName("Bezier points are returned as new instances and the input stays untouched")
    void testBezierPointsAreRecreated() {
        PathPoint bezier = new PathPoint("B", 10f, 20f, 30f, 40f, 50f, 60f);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(bezier), false, null, null, null, false, 1d);

        assertNotSame(bezier, result.get(0), "B points are rebuilt");
        assertEquals(10f, bezier.x1, "the input B point is not modified");
        assertEquals(60f, bezier.y3, "the input B point is not modified");
        assertMm("the returned point is converted", 10d, result.get(0).x1);
    }

    @Test
    @DisplayName("Legacy 300 DPI absolute paths are detected, rescaled and not passed through the CTM")
    void testLegacyAbsolutePathIsDetected() {
        // raw coordinates of 10 mm / 50 mm expressed in a 300 DPI device space
        double raw10 = 300d * 10d / 25.4d;
        double raw50 = 300d * 50d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
                new PathPoint("L", (float) raw50, (float) raw50, 0, 0, 0, 0));
        // the declared CTM pushes the path far outside of the page boundary
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                input, true, ctm, null, null, false, 1d);

        assertMm("legacy raw value 300dpi 10mm becomes 10 mm in points", 10d, result.get(0).x1);
        assertMm("legacy raw value 300dpi 10mm becomes 10 mm in points", 10d, result.get(0).y1);
        assertMm("legacy raw value 300dpi 50mm becomes 50 mm in points", 50d, result.get(1).x1);
        assertMm("legacy raw value 300dpi 50mm becomes 50 mm in points", 50d, result.get(1).y1);
        assertNotEquals(raw10 + 1000d, (double) result.get(0).x1, 1d,
                "the CTM must not be applied to legacy absolute coordinates");
    }

    @Test
    @DisplayName("Legacy absolute path detection still applies the origin fix")
    void testLegacyAbsolutePathWithOriginFix() {
        double raw10 = 300d * 10d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
                new PathPoint("L", (float) (300d * 50d / 25.4d), (float) (300d * 50d / 25.4d), 0, 0, 0, 0));
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                input, true, ctm, null, null, true, 1d);

        assertMm("legacy x is unchanged by the origin fix", 10d, result.get(0).x1);
        assertMm("legacy y is flipped by the origin fix", PAGE_HEIGHT - 10d, result.get(0).y1);
    }

    @Test
    @DisplayName("A scale different from one disables the legacy absolute path handling")
    void testLegacyAbsolutePathDisabledByScale() {
        double raw10 = 300d * 10d / 25.4d;
        double raw50 = 300d * 50d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
                new PathPoint("L", (float) raw50, (float) raw50, 0, 0, 0, 0));
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                input, true, ctm, null, null, false, 2d);

        // standard handling: CTM first, then the scale
        assertMm("CTM is applied and then scaled", (raw10 + 1000d) * 2d, result.get(0).x1);
        assertMm("CTM is applied and then scaled", raw10 * 2d, result.get(0).y1);
    }

    @Test
    @DisplayName("A composite object boundary disables the legacy absolute path handling")
    void testLegacyAbsolutePathDisabledByCompositeBoundary() {
        double raw10 = 300d * 10d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
                new PathPoint("L", (float) (300d * 50d / 25.4d), (float) (300d * 50d / 25.4d), 0, 0, 0, 0));
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);
        ST_Box compositeBoundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                input, true, ctm, compositeBoundary, null, false, 1d);

        assertMm("the CTM is applied because legacy handling is disabled",
                raw10 + 1000d, result.get(0).x1);
    }

    @Test
    @DisplayName("A missing boundary prevents legacy detection, so the CTM is applied as usual")
    void testNoBoundaryMeansNoLegacyDetection() {
        double raw10 = 300d * 10d / 25.4d;
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, null,
                listOf(move((float) raw10, (float) raw10)), true, ctm, null, null, false, 1d);

        assertMm("CTM translation is applied", raw10 + 1000d, result.get(0).x1);
        assertMm("CTM translation is applied", raw10 + 0d, result.get(0).y1);
    }

    @Test
    @DisplayName("Coordinate values inside the page never trigger legacy detection")
    void testSmallCoordinatesAreNotTreatedAsLegacy() {
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 0d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, null, null, false, 1d);

        assertMm("CTM scaling is applied", 20d, result.get(0).x1);
        assertMm("CTM scaling is applied", 40d, result.get(0).y1);
    }

    @Test
    @DisplayName("The nine parameter overload behaves like the ten parameter overload with scale 1")
    void testNineParameterOverloadDelegatesWithUnitScale() {
        ST_Box boundary = new ST_Box(3d, 4d, 100d, 100d);
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1d, 1d);
        ST_Box compositeBoundary = new ST_Box(2d, 2d, 40d, 40d);

        List<PathPoint> nine = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, compositeBoundary, null, false);
        List<PathPoint> ten = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, compositeBoundary, null, false, 1d);

        assertEquals(ten.size(), nine.size());
        for (int i = 0; i < ten.size(); i++) {
            assertEquals(ten.get(i).type, nine.get(i).type);
            assertEquals(ten.get(i).x1, nine.get(i).x1, 1e-6f);
            assertEquals(ten.get(i).y1, nine.get(i).y1, 1e-6f);
        }
    }

    @Test
    @DisplayName("A CTM flag without CTM data fails with a NullPointerException")
    void testCtmFlagWithoutCtmArrayFails() {
        assertThrows(NullPointerException.class, () -> PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT,
                new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT), listOf(move(10f, 20f)),
                true, null, null, null, false, 1d));
    }
}
