    @Test
    public void compositeObjectCtmIsAppliedToTheFinalPosition() {
        ST_Array compositeCtm = new ST_Array(1d, 0d, 0d, 1d, 5d, 6d);

        List<TextCodePoint> points = call(0, 0, null, 10f,
                Collections.singletonList(code("A", 1d, 2d)),
