        assertEquals(1, points.size());
        assertPosition(points.get(0), 6, 8);
    }

    @Test
    public void compositeObjectCtmIsAppliedAfterBoundaryAndScale() {
        ST_Array compositeCtm = new ST_Array(2d, 0d, 0d, 2d, 0d, 0d);
        ST_Box boundary = new ST_Box(10d, 10d, 0d, 0d);

        List<TextCodePoint> points = call(0, 0, boundary, 10f,
