package org.ofdrw.layout.element;


import org.ofdrw.core.basicStructure.pageObj.layer.Type;
import org.ofdrw.layout.Rectangle;
import org.ofdrw.layout.RenderPrepare;
import org.ofdrw.layout.element.canvas.NamedColor;
import org.ofdrw.layout.engine.ElementSplit;
import org.ofdrw.layout.handler.ElementRenderFinishHandler;

import java.util.Arrays;

/**
 * 盒式模型基础
 * <p>
 * 每个继承Div的对象都不必须提供泛型参数T,用于简化链式调用。
 * <p>
 * 绘制行为详见渲染器：{@link org.ofdrw.layout.engine.render.DivRender}
 *
 * @param <T> 链式调用返还值，Div的子类
 * @author 权观宇
 * @since 2020-02-03 12:46:15
 */
public class Div<T extends Div> implements RenderPrepare, ElementSplit {

    /**
     * 背景颜色
     * <p>
     * (R,G,B) 三色数组
     */
    private int[] backgroundColor = null;

    /**
     * 边框颜色
     * <p>
     * (R,G,B) 三色数组
     */
    private int[] borderColor = null;

    /**
     * 内容宽度
     * <p>
     * 如果不设置，则为自适应。最大宽度不能大于页面版心宽度。
     */
    private Double width = null;

    /**
     * 内容高度
     * <p>
     * 如果不设置则为自适应。
     * <p>
     * 注意如果需要保证块完整，那么高度不能大于版心高度。
     */
    private Double height = null;

    /**
     * 内边距
     * <p>
     * 数组中个元素意义：上、右、下、左
     */
    private Double[] padding = {0d, 0d, 0d, 0d};

    /**
     * 边框宽度
     * <p>
     * 数组中个元素意义：上、右、下、左
     */
    private Double[] border = {0d, 0d, 0d, 0d};

    /**
     * 外边距
     * <p>
     * 数组中个元素意义：上、右、下、左
     */
    private Double[] margin = {0d, 0d, 0d, 0d};

    /**
     * 边框虚线样式
     * <p>
     * 数组中个元素意义：[偏移量, 虚线长,空白长, 虚线长,空白长, 虚线长,空白长, 虚线长,空白长, ...]
     */
    private Double[] borderDash = null;

    /**
     * 固定布局的盒式模型左上角X坐标
     */
    private Double x = null;

    /**
     * 固定布局的盒式模型左上角y坐标
     */
    private Double y = null;

    /**
     * 对段的占用情况
     */
    private Clear clear = Clear.both;

    /**
     * 在段中的浮动方向
     * <p>
     * 为了避免与float关键字冲突采用AFloat
     */
    private AFloat aFloat = AFloat.left;

    /**
     * 相对于段的左边界距离
     */
    private double left = 0d;

    /**
     * 相对于段的右边界距离
     */
    private double right = 0d;

    /**
     * 相对坐标的top
     */
    private double top = 0d;

/**
 * 元素整体透明度
 * <p>
 * null 表示不透明
 * <p>
 * 取值区间 [0,1]
 */
private Double opacity = null;

/**
 * 元素定位方式
 * <p>
 * 默认为静态定位
 */
private Position position = Position.Static;

/**
 * 当渲染空间不足时可能会拆分元素
 * <p>
 * true为不拆分，false为拆分。默认值为false
 */
private Boolean integrity = false;

/**
 * 占位符
 * <p>
 * 不参与渲染
 */
private boolean placeholder = false;

/**
 * 图层，默认为Body
 */
private Type layer = Type.Body;

/**
 * 渲染完成后的处理器
 * 在该回调中可以获取到生成OFD元素在容器中的位置，以及过程中生成的所有OFD元素。
 */
private ElementRenderFinishHandler renderFinishHandler = null;

public Div() {
}

public Div(Double width, Double height) {
    this.width = width;
    this.height = height;
}

/**
 * 创建绝对定位的Div对象
 *
 * @param x      固定布局的盒式模型左上角X坐标
 * @param y      固定布局的盒式模型左上角y坐标
 * @param width  宽度
 * @param height 高度
 */
public Div(double x, double y, double width, double height) {
    setX(x);
    setY(y);
    setWidth(width);
    setHeight(height);
    setPosition(Position.Absolute);
}

/**
 * 是否存在边框
 *
 * @return true 不存在；false 存在
 */
public boolean isNoBorder() {
    return getBorderTop() == 0d
            && getBorderRight() == 0d
            && getBorderBottom() == 0d
            && getBorderLeft() == 0d;
}

/**
 * 是否是块级元素
 * <p>
 * 块元素将会独占整个段
 * <p>
 * 绝对定位默认不为块级元素
 *
 * @return true 独占; false 共享
 */
public boolean isBlockElement() {
    if (position == Position.Absolute) {
        return false;
    }
    /*
     独占段的元素类型
     1. 独占
     2. 浮动 + Clear 对立
     */
    return (clear == Clear.both)
            || (aFloat == AFloat.right && clear == Clear.left)
            || (aFloat == AFloat.left && clear == Clear.right);
}

/**
 * 获取透明度
 *
 * @return 透明度取值区间 [0,1]
 */
public Double getOpacity() {
    return opacity;
}

/**
 * 设置透明度
 * <p>
 * 0 - 表示全透明， 1 - 表示不透明
 *
 * @param opacity 透明度取值区间 [0,1]
 * @return this
 */
public T setOpacity(Double opacity) {
    if (opacity == null) {
    } else if (opacity > 1) {
        opacity = 1d;
    } else if (opacity < 0) {
        opacity = 0d;
    }
    this.opacity = opacity;
    return (T) this;
}

/**
 * 获取 边框颜色
 *
 * @return 边框颜色 RGB值，null 表示无色。
 */
public int[] getBorderColor() {
    return borderColor;
}

/**
 * 设置边框颜色
 *
 * @param r 红色值（0~255）
 * @param g 绿色值（0~255）
 * @param b 蓝色值（0~255）
 * @return this
 */
public T setBorderColor(int r, int g, int b) {
    this.borderColor = new int[]{r, g, b};
    return (T) this;
}

/**
 * 设置 边框颜色
 *
 * @param rgb RGB数组，null 表示无色。
 * @return this
 */
public T setBorderColor(int[] rgb) {
    this.borderColor = rgb;
    return (T) this;
}

/**
 * 设置 边框颜色
 *
 * @param color 颜色值，可以是 16进制值 "#FFFFFF"、 16进制值缩写 "#FF"F、RGB "rgb(255,255,255)"、颜色名称 "white"
 * @return this
 */
public T setBorderColor(String color) {
    int[] c = NamedColor.rgb(color);
    if (c == null || c.length < 3) {
        throw new IllegalArgumentException("边框颜色 颜色值错误：" + color);
    }
    this.setBorderColor(c);
    return (T) this;
}

