            return new LinkedList<>();
        }
        String[] arr = dataStr.split("\\s+");
        LinkedList<OptVal> res = new LinkedList<>();
        String opt = null;
        List<String> values = new LinkedList<>();
        for (String s : arr) {
            if (s.isEmpty()) {
                // 跳过split产生的空字符串（如前导空格导致的""）
                continue;
            }
            switch (s) {
                case "S":
                case "M":
                case "L":
                case "Q":
                case "B":
                case "A":
                case "C":
                case "CM":
                    if (opt != null) {
                        res.add(new OptVal(opt, values));
                    }
                    values = new LinkedList<>();
                    opt = s;
                    break;
                default:
                    values.add(s);
            }
        }
        if (opt != null) {
            res.add(new OptVal(opt, values));
        }
        return res;
    }

