package org.ofdrw.layout.engine.render;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicStructure.pageObj.layer.PageBlockType;
import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.core.basicStructure.pageObj.layer.block.PathObject;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.graph.pathObj.AbbreviatedData;
import org.ofdrw.core.graph.pathObj.OptVal;
import org.ofdrw.layout.element.Div;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link DivRender#render(CT_PageBlock, Div, AtomicInteger)} 的单元测试。
 * <p>
 * 覆盖：绘制入口的前置条件（无背景无边框直接返回、高度必须指定）、背景绘制、
 * 等宽边框绘制、不等宽边框逐边绘制、透明度、边框颜色、虚线样式、以及最大图元ID的自增行为。
 */
@DisplayName("Div 盒式模型渲染器测试")
public class DivRenderRenderTests {

    private static final double DELTA = 1e-6;

    /* ------------------------------------------------------------------ 工具方法 */

    private static CT_PageBlock newLayer() {
        return new CT_PageBlock();
    }

    /**
     * 创建一个指定位置与尺寸的 Div
     */
    private static Div<?> div(double x, double y, double width, double height) {
        Div<?> d = new Div();
        d.setX(x);
        d.setY(y);
        d.setWidth(width);
        d.setHeight(height);
        return d;
    }

    /**
     * 把图层内容全部取出并断言都是 PathObject
     */
    @SuppressWarnings("unchecked")
    private static List<PathObject> paths(CT_PageBlock layer) {
        List<PathObject> res = new ArrayList<>();
        for (PageBlockType pb : layer.getPageBlocks()) {
            assertNotNull(pb, "图层中不应出现无法识别的页块元素");
            assertTrue(pb instanceof PathObject,
                    "Div 渲染只会产生 PathObject，实际为: " + pb.getClass().getName());
            res.add((PathObject) pb);
        }
        return res;
    }

    private static void assertBoundary(PathObject p, double x, double y, double w, double h) {
        ST_Box b = p.getBoundary();
        assertNotNull(b, "图元必须设置外接矩形");
        assertEquals(x, b.getTopLeftX(), DELTA, "外接矩形左上角X");
        assertEquals(y, b.getTopLeftY(), DELTA, "外接矩形左上角Y");
        assertEquals(w, b.getWidth(), DELTA, "外接矩形宽度");
        assertEquals(h, b.getHeight(), DELTA, "外接矩形高度");
    }

    private static LinkedList<OptVal> ops(PathObject p) {
        AbbreviatedData data = p.getAbbreviatedDataEle();
        assertNotNull(data, "图元必须设置图形轮廓数据");
        return data.getRawOptVal();
    }

    private static void assertRectPath(PathObject p, double x, double y, double w, double h) {
        LinkedList<OptVal> ops = ops(p);
        assertEquals(5, ops.size(), "矩形轮廓应包含 M、3个 L 与 C 共5个操作");
        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{x, y}, ops.get(0).getValues(), DELTA, "矩形起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{x + w, y}, ops.get(1).getValues(), DELTA, "矩形右上角");
        assertEquals("L", ops.get(2).getOpt());
        assertArrayEquals(new double[]{x + w, y + h}, ops.get(2).getValues(), DELTA, "矩形右下角");
        assertEquals("L", ops.get(3).getOpt());
        assertArrayEquals(new double[]{x, y + h}, ops.get(3).getValues(), DELTA, "矩形左下角");
        assertEquals("C", ops.get(4).getOpt());
    }

    private static void assertLinePath(PathObject p, double fromX, double fromY) {
        LinkedList<OptVal> ops = ops(p);
        assertEquals(2, ops.size(), "线条轮廓应包含 M 与 L 共2个操作");
        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{fromX, fromY}, ops.get(0).getValues(), DELTA, "线条起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{fromX, fromY}, ops.get(1).getValues(), DELTA, "线条终点");
    }

    private static String rgb(PathObject p, boolean fill) {
        if (fill) {
            assertNotNull(p.getFillColor(), "应存在填充颜色");
            return p.getFillColor().getValue().toString();
        }
        assertNotNull(p.getStrokeColor(), "应存在描边颜色");
        return p.getStrokeColor().getValue().toString();
    }

    /* ------------------------------------------------------------------ 前置条件 */

    @Test
    @DisplayName("无背景色且无边框：直接返回，不产生图元、不消耗ID")
    void noBackgroundAndNoBorder_skipsRendering() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(100);
        Div<?> e = div(10, 20, 100, 50);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "无背景无边框的Div不应产生任何图元");
        assertEquals(100, maxUnitID.get(), "未绘制任何图元时不应消耗ID");
    }

    @Test
    @DisplayName("无背景色且无边框：即使高度未指定也不抛异常（先返回）")
    void noBackgroundAndNoBorderWithoutHeight_doesNotThrow() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(7);
        Div<?> e = new Div();
        e.setWidth(100d);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(7, maxUnitID.get());
    }

    @Test
    @DisplayName("存在背景色但高度为null：抛出IllegalArgumentException且不绘制")
    void nullHeightWithBackground_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
        Div<?> e = new Div();
        e.setX(0d);
        e.setY(0d);
        e.setWidth(100d);
        e.setBackgroundColor(255, 0, 0);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> DivRender.render(layer, e, maxUnitID));
        assertNotNull(ex.getMessage());
        assertTrue(ex.getMessage().contains("高度"), "异常信息应指明高度必须指定，实际：" + ex.getMessage());
        assertTrue(layer.getPageBlocks().isEmpty(), "高度校验失败时不应绘制任何图元");
        assertEquals(1, maxUnitID.get());
    }

    @Test
    @DisplayName("只有边框且高度为null：同样抛出IllegalArgumentException")
    void nullHeightWithBorder_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
        Div<?> e = new Div();
        e.setX(0d);
        e.setY(0d);
        e.setWidth(100d);
        e.setBorder(1d);

        assertThrows(IllegalArgumentException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(1, maxUnitID.get());
    }

    /* ------------------------------------------------------------------ 背景绘制 */

    @Test
    @DisplayName("仅有背景色、无边框：绘制背景矩形，同时等宽分支绘制零宽边框")
    void backgroundOnly_drawsBackgroundAndZeroWidthBorder() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBackgroundColor(10, 20, 30);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size(), "背景 + 等宽分支的边框");

        PathObject bg = blocks.get(0);
        assertBoundary(bg, 10, 20, 100, 50);
        assertRectPath(bg, 0, 0, 100, 50);
        assertEquals(Boolean.FALSE, bg.getStroke(), "背景不描边");
        assertEquals(Boolean.TRUE, bg.getFill(), "背景填充");
        assertEquals("10 20 30", rgb(bg, true), "背景填充颜色应为设置的RGB");
        assertNull(bg.getLineWidth(), "背景不设置线宽");
        assertEquals(Integer.valueOf(255), bg.getAlpha(), "未设置透明度时alpha缺省为255");

        PathObject border = blocks.get(1);
        assertBoundary(border, 10, 20, 100, 50);
        assertEquals(0d, border.getLineWidth(), DELTA, "四边为0时等宽分支的线宽为0");
    }

    @Test
    @DisplayName("背景绘制考虑外边距、内边距与边框宽度")
    void backgroundWithBoxModel_usesExpectedBoundary() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBackgroundColor(10, 20, 30);
        e.setMargin(5d, 6d, 7d, 8d);   // 上 右 下 左
        e.setPadding(1d, 2d, 3d, 4d);  // 上 右 下 左
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());

        // x = 10 + marginLeft(8) + borderLeft(2) = 20
        // y = 20 + marginTop(5) + borderTop(2) = 27
        // w = paddingLeft(4) + width(100) + paddingRight(2) = 106
        // h = paddingTop(1) + height(50) + paddingBottom(3) = 54
        PathObject bg = blocks.get(0);
        assertBoundary(bg, 20, 27, 106, 54);
        assertRectPath(bg, 0, 0, 106, 54);
    }

    @Test
    @DisplayName("内容高度为0时不绘制背景，但边框仍然绘制")
    void zeroContentHeight_skipsBackground() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 0);
        e.setBackgroundColor(200, 200, 200);

        DivRender.render(layer, e, maxUnitID);

