        assertEquals(0d, border.getLineWidth(), DELTA);
    }

    @Test
    @DisplayName("缺少X坐标时无法计算位置：抛出NullPointerException")
    void missingCoordinate_throwsNullPointerException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = new Div();
        e.setY(0d);
        e.setWidth(100d);
        e.setHeight(50d);
        e.setBackgroundColor(1, 2, 3);

