        assertEquals(2, blocks.size());

        // x = 10 + marginLeft(8) + borderLeft(2) = 20
        // y = 20 + marginTop(5) + borderTop(2) = 27
        // w = paddingLeft(4) + width(100) + paddingRight(2) = 106
        // h = paddingTop(1) + height(50) + paddingBottom(3) = 54
        PathObject bg = blocks.get(0);
        assertBoundary(bg, 20, 27, 106, 54);
        assertRectPath(bg, 0, 0, 106, 54);
    }

    @Test
    @DisplayName("内容高度为0时不绘制背景，但边框仍然绘制")
    void zeroContentHeight_skipsBackground() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 0);
        e.setBackgroundColor(200, 200, 200);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "内容高度为0时不绘制背景，只绘制边框");
        PathObject border = blocks.get(0);
        assertNull(border.getFillColor(), "仅边框的图元没有填充色");
        assertEquals(0d, border.getLineWidth(), DELTA);
    }

    @Test
    @DisplayName("缺少X坐标时无法计算位置：抛出NullPointerException")
    void missingCoordinate_throwsNullPointerException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = new Div();
        e.setY(0d);
        e.setWidth(100d);
        e.setHeight(50d);
        e.setBackgroundColor(1, 2, 3);

        assertThrows(NullPointerException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(layer.getPageBlocks().isEmpty());
    }

    /* ------------------------------------------------------------------ 等宽边框 */

    @Test
    @DisplayName("等宽边框：绘制单个边框矩形，边界与线宽符合盒式模型")
    void uniformBorder_drawsSingleBorderRect() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setPadding(1d, 2d, 3d, 4d);
        e.setMargin(5d, 6d, 7d, 8d);
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "四边宽度一致时只绘制1个边框图元");
        PathObject border = blocks.get(0);
        // x = 10 + 8 = 18, y = 20 + 5 = 25
        // w = 2 + 4 + 100 + 2 + 2 = 110, h = 2 + 1 + 50 + 3 + 2 = 58
        assertBoundary(border, 18, 25, 110, 58);
        assertEquals(2d, border.getLineWidth(), DELTA, "线宽为边框宽度");
        assertRectPath(border, 1, 1, 108, 56);
        assertNull(border.getStrokeColor(), "未设置边框颜色时使用默认黑色（无颜色元素）");
        assertNull(border.getFillColor(), "边框图元不填充");
        assertEquals(Integer.valueOf(255), border.getAlpha());
    }

    @Test
    @DisplayName("等宽边框：设置边框颜色后写入描边颜色")
    void uniformBorder_withColor_setsStrokeColor() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 80, 40);
        e.setBorder(3d);
        e.setBorderColor(255, 128, 0);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size());
        assertEquals("255 128 0", rgb(blocks.get(0), false));
    }

    @Test
    @DisplayName("等宽边框：宽度差异小于0.001时仍视为等宽（STBase.fmt精度）")
    void nearEqualBorders_treatedAsUniform() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorderTop(2.0001);
        e.setBorderRight(2.0002);
        e.setBorderBottom(2.0003);
        e.setBorderLeft(2.0004);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "格式化后相等的边框宽度按等宽处理");
        assertEquals(2.0001, blocks.get(0).getLineWidth(), 1e-9, "等宽分支使用上边框宽度作为线宽");
    }

    /* ------------------------------------------------------------------ 透明度 */

    @Test
    @DisplayName("透明度：0.5转换为127，并同时作用于背景与边框")
    void opacity_appliedAsAlpha() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBackgroundColor(1, 2, 3);
        e.setBorder(2d);
        e.setOpacity(0.5);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());
        assertEquals(Integer.valueOf(127), blocks.get(0).getAlpha(), "0.5 * 255 = 127.5 取整为127");
        assertEquals(Integer.valueOf(127), blocks.get(1).getAlpha());
    }

    @Test
    @DisplayName("透明度边界值：0 -> alpha 0，1 -> alpha 255")
    void opacityBoundaries_appliedAsAlpha() {
        CT_PageBlock layer = newLayer();
        Div<?> transparent = div(0, 0, 100, 50);
        transparent.setBorder(1d);
        transparent.setOpacity(0d);
        DivRender.render(layer, transparent, new AtomicInteger(0));

        CT_PageBlock opaqueLayer = newLayer();
        Div<?> opaque = div(0, 0, 100, 50);
        opaque.setBorder(1d);
        opaque.setOpacity(1d);
        DivRender.render(opaqueLayer, opaque, new AtomicInteger(0));

        assertEquals(Integer.valueOf(0), paths(layer).get(0).getAlpha());
        assertEquals(Integer.valueOf(255), paths(opaqueLayer).get(0).getAlpha());
    }

    /* ------------------------------------------------------------------ 虚线 */

    @Test
    @DisplayName("单参数虚线：虚线与空白等长，且不设置偏移量")
    void singleValueDash_setsPatternWithoutOffset() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);
        e.setBorderDash(3d);

        DivRender.render(layer, e, maxUnitID);

        PathObject border = paths(layer).get(0);
        assertNotNull(border.getDashPattern(), "应设置虚线样式");
        assertEquals("3 3", border.getDashPattern().toString());
        assertEquals(0d, border.getDashOffset(), DELTA, "偏移量为0时不下发DashOffset");
    }

    @Test
    @DisplayName("带偏移量的虚线：写入DashOffset与DashPattern")
    void dashWithOffset_setsOffsetAndPattern() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);
        e.setBorderDash(1d, 3d, 2d);

        DivRender.render(layer, e, maxUnitID);

        PathObject border = paths(layer).get(0);
        assertEquals(1d, border.getDashOffset(), DELTA);
        assertEquals("3 2", border.getDashPattern().toString());
    }

    @Test
    @DisplayName("未设置虚线时不写入虚线相关属性")
    void noDash_noDashAttributes() {
        CT_PageBlock layer = newLayer();
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);

        DivRender.render(layer, e, new AtomicInteger(0));

        PathObject border = paths(layer).get(0);
        assertNull(border.getDashPattern(), "未设置虚线时不应有DashPattern");
    }

    /* ------------------------------------------------------------------ 不等宽边框 */

    @Test
    @DisplayName("不等宽边框：按 上、下、左、右 顺序分别绘制4条边")
    void nonUniformBorders_drawsFourEdgesInOrder() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBorder(2d, 4d, 6d, 8d); // 上 右 下 左
        e.setBorderColor(0, 0, 255);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size(), "不等宽边框逐边绘制，共4个图元");

        PathObject top = blocks.get(0);
        assertBoundary(top, 10, 20, 112, 2);
        assertEquals(2d, top.getLineWidth(), DELTA);
        assertLinePath(top, 0, 1);
        assertEquals("0 0 255", rgb(top, false));

        PathObject bottom = blocks.get(1);
        // y = 20 + 0 + 2 + 0 + 50 + 0 = 72
        assertBoundary(bottom, 10, 72, 112, 6);
        assertEquals(6d, bottom.getLineWidth(), DELTA);
        assertLinePath(bottom, 0, 3);

        PathObject left = blocks.get(2);
        // y = 20 + 0 + topWidth(2) = 22；h = 2 + 0 + 50 + 0 + 6 - 2 - 6 = 50
        assertBoundary(left, 10, 22, 8, 50);
        assertEquals(8d, left.getLineWidth(), DELTA);
        assertLinePath(left, 4, 0);

        PathObject right = blocks.get(3);
        // x = 10 + 0 + 8 + 0 + 100 + 0 = 118
        assertBoundary(right, 118, 22, 4, 50);
        assertEquals(4d, right.getLineWidth(), DELTA);
        assertLinePath(right, 2, 0);
    }

    @Test
    @DisplayName("不等宽边框：宽度为0的边被跳过")
    void nonUniformBorders_skipsZeroWidthEdges() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(0d, 4d, 0d, 8d); // 上、下无边框

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size(), "只绘制左边与右边");
        assertEquals(8d, blocks.get(0).getLineWidth(), DELTA, "先绘制左边");
        assertEquals(4d, blocks.get(1).getLineWidth(), DELTA, "再绘制右边");
        assertBoundary(blocks.get(0), 0, 0, 8, 50);
        assertBoundary(blocks.get(1), 108, 0, 4, 50);
    }

    @Test
    @DisplayName("不等宽边框：内容高度与上下边框都为0时视为占位符，跳过左右边绘制")
    void zeroContentAndNoVerticalBorders_skipsAllEdges() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(30);
        Div<?> e = div(0, 0, 100, 0);
        e.setBorder(0d, 4d, 0d, 8d);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "占位符元素不应绘制任何图元");
        assertEquals(30, maxUnitID.get(), "占位符不消耗图元ID");
    }

    @Test
    @DisplayName("不等宽边框：透明度与虚线同样作用于各条边")
    void nonUniformBorders_applyAlphaAndDash() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d, 2d, 3d, 4d);
        e.setOpacity(1d);
        e.setBorderDash(2d, 1d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size());
        for (PathObject p : blocks) {
            assertEquals(Integer.valueOf(255), p.getAlpha(), "透明度 1.0 对应 alpha 255");
            assertNotNull(p.getDashPattern(), "每条边都应设置虚线样式");
            assertEquals("2 1", p.getDashPattern().toString());
        }
    }

    /* ------------------------------------------------------------------ 图元ID */

    @Test
    @DisplayName("图元ID：按绘制顺序自增，最终写入PathObject与计数器")
    void maxUnitID_incrementedPerDrawnUnit() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(40);
        Div<?> e = div(0, 0, 100, 50);
        e.setBackgroundColor(1, 1, 1);
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());
        assertNotNull(blocks.get(0).getID());
        assertNotNull(blocks.get(1).getID());
        assertEquals(Long.valueOf(41L), blocks.get(0).getID().getId(), "背景使用第1个新ID");
        assertEquals(Long.valueOf(42L), blocks.get(1).getID().getId(), "边框使用第2个新ID");
        assertEquals(42, maxUnitID.get(), "计数器应推进到最后一个分配的ID");
        assertFalse(blocks.get(0).getID().getId().equals(blocks.get(1).getID().getId()),
                "不同图元的ID必须不同");
    }

    @Test
    @DisplayName("图元ID：不等宽边框逐边分配ID")
    void maxUnitID_incrementedPerEdge() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d, 2d, 3d, 4d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size());
        for (int i = 0; i < blocks.size(); i++) {
            assertEquals(Long.valueOf((long) (i + 1)), blocks.get(i).getID().getId(),
                    "第" + (i + 1) + "个图元的ID应为" + (i + 1));
        }
        assertEquals(4, maxUnitID.get());
    }
}
