private void containerInit() {
    CT_DocInfo docInfo = new CT_DocInfo()
            .setDocID(UUID.randomUUID())
            .setCreationDate(LocalDate.now())
            .setCreator("OFD R&W")
            .setCreatorVersion(GlobalVar.Version);
