import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * {@link ParagraphRender#render(CT_PageBlock, ResManager, Paragraph, AtomicInteger)} 的单元测试。
 * <p>
 * 测试统一使用“宽度映射表”字体（每个 ASCII 字符宽度 == 字号），因此字符宽度、行高
 * 与运行环境中的系统字体无关，结果完全确定：
 * <ul>
 *     <li>字号 10mm，字符宽度 10mm，字符高度 10mm</li>
 *     <li>默认行间距 2mm，因此行高度 = 12mm</li>
 * </ul>
 */
public class ParagraphRenderRenderTests {

    /**
     * 测试用字号（mm）
     */
    private static final double FONT_SIZE = 10d;

    /**
     * 行高度 = 行内最高字符高度(10) + 行间距(2)
     */
    private static final double LINE_HEIGHT = FONT_SIZE + 2d;

    /**
     * 比较浮点数使用的容差
     */
    private static final double EPS = 1e-6;

    private OFDDir ofdDir;

    private DocDir docDir;

    private Font font;

    private ResManager resManager;

    private AtomicInteger maxUnitID;

    private CT_PageBlock layer;

    @BeforeEach
    void setUp() {
        // 构建一个最小可用的OFD虚拟容器，用于资源管理器工作
        ofdDir = OFDDir.newOFD();
        docDir = ofdDir.newDoc();
        Document document = new Document();
        document.setCommonData(new CT_CommonData());
        docDir.setDocument(document);

        font = uniformWidthFont("OFDRW-Test-Font");
        maxUnitID = new AtomicInteger(100);
        resManager = new ResManager(ofdDir, docDir, maxUnitID);
        layer = new CT_PageBlock();
    }

    @AfterEach
    void tearDown() {
        if (ofdDir != null) {
            ofdDir.clean();
        }
    }

    // ------------------------------------------------------------------
    // 正常流程
    // ------------------------------------------------------------------

    @Test
    @DisplayName("段落实例为null时不做任何渲染，也不消耗对象ID")
    void render_nullParagraph_doesNothing() {
        ParagraphRender.render(layer, resManager, null, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "null段落不应产生任何图元");
        assertEquals(100, maxUnitID.get(), "null段落不应消耗对象ID");
        assertTrue(resManager.getNewResIds().isEmpty(), "null段落不应注册字体资源");
    }

    @Test
    @DisplayName("空段落（没有文字内容）不产生图元也不注册资源")
    void render_emptyParagraph_doesNothing() {
        Paragraph paragraph = new Paragraph().setWidth(50d);

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "空段落不应产生任何图元");
        assertTrue(paragraph.getLines().isEmpty(), "空段落预处理后仍然没有行");
        assertEquals(100, maxUnitID.get(), "空段落不应消耗对象ID");
        assertTrue(resManager.getNewResIds().isEmpty(), "空段落不应注册字体资源");
    }

    @Test
    @DisplayName("单个Span被渲染为一个文字对象，包含边界、字体、字号与文字定位信息")
    void render_singleSpan_createsTextObject() {
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "AB"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<TextObject> texts = textObjects(layer);
        assertEquals(1, texts.size(), "一行一个Span应只产生一个文字对象");

        TextObject txt = texts.get(0);
        ST_Box box = txt.getBoundary();
        assertNotNull(box);
        assertEquals(0d, box.getTopLeftX(), EPS, "无外边距/边框/内边距时行起始X为元素X");
        assertEquals(0d, box.getTopLeftY(), EPS, "首个行块的Y为元素Y");
        assertEquals(2 * FONT_SIZE, box.getWidth(), EPS, "文字对象宽度为Span内容宽度");
        assertEquals(LINE_HEIGHT, box.getHeight(), EPS, "文字对象高度为整行高度");

        assertEquals(FONT_SIZE, txt.getSize(), EPS, "文字对象字号应来自Span");

        // 字体资源被注册并引用
        assertEquals(1, resManager.getNewResIds().size(), "Span字体应被注册到资源管理器");
        ST_ID fontId = resManager.getNewResIds().get(0);
        assertNotNull(txt.getFont(), "文字对象应引用字体资源");
        assertEquals(fontId.getId(), txt.getFont().getRefId().getId(), "文字对象应引用已注册的字体资源");

        // 文字内容与定位点
        List<TextCode> codes = txt.getTextCodes();
        assertEquals(1, codes.size(), "一个Span只包含一个TextCode");
        TextCode code = codes.get(0);
        assertEquals("AB", code.getContent(), "TextCode内容为Span文字");
        assertEquals(0d, code.getX(), EPS, "TextCode的X偏移为0");
        assertEquals(FONT_SIZE, code.getY(), EPS, "TextCode的Y偏移为行内最高字符高度");
        Double[] deltaX = code.getDeltaX().toDouble();
        assertEquals(1, deltaX.length, "2个字符应只有1个字符偏移量");
        assertEquals(FONT_SIZE, deltaX[0], EPS, "字符偏移量为字符宽度");

        // 未设置的样式使用默认值
        assertEquals(Weight.W_400, txt.getWeight(), "未设置粗细时使用默认粗细400");
        assertFalse(txt.getItalic(), "默认不是斜体");
        assertTrue(txt.getFill(), "默认填充");
        assertNull(txt.getFillColor(), "默认颜色为黑色（不写入FillColor）");
        assertEquals(255, txt.getAlpha(), "默认不透明");
    }

    @Test
    @DisplayName("行内多个Span依次向右排列，坐标连续累加")
    void render_multipleSpansInLine_offsetsAreAccumulated() {
        Paragraph paragraph = new Paragraph().setWidth(200d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));
        paragraph.add(new Span(font, FONT_SIZE, "B"));
        paragraph.add(new Span(font, FONT_SIZE, "C"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<TextObject> texts = textObjects(layer);
        assertEquals(3, texts.size());
        assertEquals(0d, texts.get(0).getBoundary().getTopLeftX(), EPS);
        assertEquals(FONT_SIZE, texts.get(1).getBoundary().getTopLeftX(), EPS);
        assertEquals(2 * FONT_SIZE, texts.get(2).getBoundary().getTopLeftX(), EPS);
        for (TextObject txt : texts) {
            assertEquals(0d, txt.getBoundary().getTopLeftY(), EPS, "同一行内的Span的Y相同");
            assertEquals(FONT_SIZE, txt.getBoundary().getWidth(), EPS);
        }
        assertEquals("A", texts.get(0).getTextCodes().get(0).getContent());
        assertEquals("B", texts.get(1).getTextCodes().get(0).getContent());
        assertEquals("C", texts.get(2).getTextCodes().get(0).getContent());
    }

    @Test
    @DisplayName("文字对齐方式决定首字符的X坐标：left/center/right")
    void render_textAlign_offsetsTextHorizontally() {
        // 行内文字宽度 2 * 10 = 20，段落宽度 50，可用剩余宽度 30
        assertEquals(0d, renderedTextX(TextAlign.left), EPS, "左对齐时文字紧贴行起始X");
        assertEquals(15d, renderedTextX(TextAlign.center), EPS, "居中对齐时左右剩余宽度均分");
        assertEquals(30d, renderedTextX(TextAlign.right), EPS, "右对齐时文字紧贴行结束X");
    }

    @Test
    @DisplayName("盒式模型（x/y、外边距、边框、内边距）参与行起始坐标计算")
    void render_boxModel_offsetsLineStart() {
        Paragraph paragraph = new Paragraph().setWidth(50d)
                .setX(5d)
                .setY(7d)
                // 上、右、下、左
                .setMargin(1d, 2d, 3d, 4d)
                .setBorder(1d)
                .setPadding(2d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<TextObject> texts = textObjects(layer);
        assertEquals(1, texts.size());
        ST_Box box = texts.get(0).getBoundary();
        // X = 5 + 左外边距4 + 左边框1 + 左内边距2
        assertEquals(12d, box.getTopLeftX(), EPS, "行起始X应叠加X、左外边距、左边框、左内边距");
        // Y = 7 + 上外边距1 + 上边框1 + 上内边距2
        assertEquals(11d, box.getTopLeftY(), EPS, "行起始Y应叠加Y、上外边距、上边框、上内边距");
    }

    @Test
    @DisplayName("Span的加粗、粗细、斜体、不填充、颜色样式被写入文字对象")
    void render_spanStyles_areAppliedToTextObject() {
        Span bold = new Span(font, FONT_SIZE, "A").setBold(true);
        Span weighted = new Span(font, FONT_SIZE, "B")
                .setWeight(Weight.W_600)
                .setItalic(true);
        Span notFilled = new Span(font, FONT_SIZE, "C")
                .setFill(false)
                .setColor(255, 0, 0);

        Paragraph paragraph = new Paragraph().setWidth(200d);
        paragraph.add(bold).add(weighted).add(notFilled);

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<TextObject> texts = textObjects(layer);
        assertEquals(3, texts.size());

        TextObject boldObj = texts.get(0);
        assertEquals(Weight.W_800, boldObj.getWeight(), "加粗等价于粗细800");
        assertFalse(boldObj.getItalic());

        TextObject weightedObj = texts.get(1);
        assertEquals(Weight.W_600, weightedObj.getWeight(), "显式粗细优先于加粗标识");
        assertTrue(weightedObj.getItalic(), "斜体标识应被写入文字对象");

        TextObject notFilledObj = texts.get(2);
        assertFalse(notFilledObj.getFill(), "setFill(false) 应写入文字对象");
        assertNotNull(notFilledObj.getFillColor(), "设置了颜色应写入FillColor");
        assertArrayEquals(new Integer[]{255, 0, 0}, notFilledObj.getFillColor().getValue().toInt());
        assertNull(texts.get(0).getFillColor(), "未设置颜色不应写入FillColor");
        assertTrue(texts.get(0).getFill(), "未设置填充时默认为填充");
    }

    @Test
    @DisplayName("带有下划线的Span额外渲染一条路径对象（默认线宽为字号的0.05倍）")
    void render_underline_createsPathObject() {
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A")
                .setUnderline(true)
                .setColor(0, 0, 255));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<PageBlockType> blocks = layer.getPageBlocks();
        assertEquals(2, blocks.size(), "下划线应额外产生一个路径对象");
        assertTrue(blocks.get(0) instanceof TextObject, "文字对象先于下划线加入图层");
        assertTrue(blocks.get(1) instanceof PathObject, "文字对象之后加入下划线路径");

        TextObject txt = (TextObject) blocks.get(0);
        PathObject underline = (PathObject) blocks.get(1);

        assertEquals(txt.getBoundary().getWidth(), underline.getBoundary().getWidth(), EPS,
                "下划线宽度与文字对象宽度一致");
        assertEquals(txt.getBoundary().getHeight(), underline.getBoundary().getHeight(), EPS,
                "下划线区域与文字对象区域一致");
        assertEquals(FONT_SIZE * 0.05, underline.getLineWidth(), EPS,
                "下划线线宽默认为字号的0.05倍");
        assertNotNull(underline.getStrokeColor(), "下划线应使用Span颜色作为描边颜色");
        assertArrayEquals(new Integer[]{0, 0, 255}, underline.getStrokeColor().getValue().toInt());

        LinkedList<OptVal> path = underline.getAbbreviatedDataEle().getRawOptVal();
        assertEquals(2, path.size(), "下划线由移动与连线两个操作符组成");
        assertEquals("M", path.get(0).getOpt());
        assertEquals(0d, path.get(0).getValues()[0], EPS);
        assertEquals(FONT_SIZE + 1.2d, path.get(0).getValues()[1], EPS,
                "下划线的Y偏移 = 行内最高字符高度 + 下划线偏移量(默认1.2)");
        assertEquals("L", path.get(1).getOpt());
        assertEquals(FONT_SIZE, path.get(1).getValues()[0], EPS, "下划线终点X为文字对象宽度");
        assertEquals(FONT_SIZE + 1.2d, path.get(1).getValues()[1], EPS);
    }

    @Test
    @DisplayName("下划线的偏移量与线宽可以被显式指定")
    void render_underlineWithCustomOffsetAndWidth() {
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A").setUnderline(true, 2d, 0.3d));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        PathObject underline = (PathObject) layer.getPageBlocks().get(1);
        assertEquals(0.3d, underline.getLineWidth(), EPS, "下划线线宽使用显式设置值");
        LinkedList<OptVal> path = underline.getAbbreviatedDataEle().getRawOptVal();
        assertEquals(FONT_SIZE + 2d, path.get(0).getValues()[1], EPS,
                "下划线Y偏移 = 行内最高字符高度 + 显式偏移量");
        assertNull(underline.getStrokeColor(), "未设置颜色时下划线不写入描边颜色");
    }

    @Test
    @DisplayName("段落透明度被写入文字对象与下划线对象")
    void render_opacity_appliedToTextAndUnderline() {
        Paragraph paragraph = new Paragraph().setWidth(50d).setOpacity(0.5d);
        paragraph.add(new Span(font, FONT_SIZE, "A").setUnderline(true));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        List<PageBlockType> blocks = layer.getPageBlocks();
        assertEquals(2, blocks.size());
        assertEquals(127, ((TextObject) blocks.get(0)).getAlpha(), "透明度 0.5 应写入 127");
        assertEquals(127, ((PathObject) blocks.get(1)).getAlpha(), "下划线透明度同样被写入");
    }

    @Test
    @DisplayName("未设置透明度时不写入Alpha属性（默认255）")
    void render_withoutOpacity_leavesDefaultAlpha() {
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

