    @Test
    @DisplayName("自动换行时每一行从行起始X开始，Y坐标按行高递增")
    void render_wrappedLines_stackVertically() {
        // 段落宽度 25，每个字符宽度 10，因此每行最多容纳2个字符
        Paragraph paragraph = new Paragraph().setWidth(25d);
        paragraph.add(new Span(font, FONT_SIZE, "AAAAA"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        LinkedList<TxtLineBlock> lines = paragraph.getLines();
        assertEquals(3, lines.size(), "5个字符应在宽度25的段落中排为3行");

        List<TextObject> texts = textObjects(layer);
        assertEquals(5, texts.size(), "未限制高度时应渲染所有行");
        assertEquals("AA", texts.get(0).getTextCodes().get(0).getContent());
        assertEquals("AA", texts.get(1).getTextCodes().get(0).getContent());
        assertEquals("A", texts.get(2).getTextCodes().get(0).getContent());
        assertEquals("AA", texts.get(3).getTextCodes().get(0).getContent());
        assertEquals("A", texts.get(4).getTextCodes().get(0).getContent());

        // 第一行两个Span均为Y=0，第二行Y=12，第三行Y=24
        assertEquals(0d, texts.get(0).getBoundary().getTopLeftY(), EPS);
        assertEquals(0d, texts.get(1).getBoundary().getTopLeftY(), EPS);
        assertEquals(LINE_HEIGHT, texts.get(2).getBoundary().getTopLeftY(), EPS);
        assertEquals(LINE_HEIGHT, texts.get(3).getBoundary().getTopLeftY(), EPS);
        assertEquals(2 * LINE_HEIGHT, texts.get(4).getBoundary().getTopLeftY(), EPS);
        // 行首Span的X总是行起始X
        assertEquals(0d, texts.get(2).getBoundary().getTopLeftX(), EPS);
        assertEquals(0d, texts.get(4).getBoundary().getTopLeftX(), EPS);
    }

    @Test
    @DisplayName("段落高度恰好容纳一行时只渲染第一行，边界情况不舍入超出的行")
    void render_containerHeight_exactlyOneLine() {
        List<TextObject> texts = renderWrappedParagraph(LINE_HEIGHT);

        assertEquals(2, texts.size(), "高度恰好为一行时应渲染第一行的2个字符");
        assertEquals("AA", texts.get(0).getTextCodes().get(0).getContent());
        assertEquals("AA", texts.get(1).getTextCodes().get(0).getContent());
    }

    @Test
    @DisplayName("段落高度小于一行时没有任何内容被渲染")
    void render_containerHeight_smallerThanOneLine() {
        List<TextObject> texts = renderWrappedParagraph(LINE_HEIGHT - 0.1d);

        assertTrue(texts.isEmpty(), "容器高度不足一行时所有内容被舍弃");
        assertTrue(resManager.getNewResIds().isEmpty(), "未渲染文字时不应注册字体");
        assertEquals(100, maxUnitID.get(), "未渲染文字时不应消耗对象ID");
    }

    @Test
    @DisplayName("段落高度可以容纳两行时，第三行被舍弃")
    void render_containerHeight_exactlyTwoLines() {
        List<TextObject> texts = renderWrappedParagraph(2 * LINE_HEIGHT);

        assertEquals(4, texts.size(), "高度为两行时只有前两行被渲染");
        assertEquals(0d, texts.get(0).getBoundary().getTopLeftY(), EPS);
        assertEquals(0d, texts.get(1).getBoundary().getTopLeftY(), EPS);
        assertEquals(LINE_HEIGHT, texts.get(2).getBoundary().getTopLeftY(), EPS);
        assertEquals(LINE_HEIGHT, texts.get(3).getBoundary().getTopLeftY(), EPS);
    }

