    @Test
    @DisplayName("相同字体只注册一次资源，对象ID由提供器依次分配")
    void render_sameFont_reusesResourceAndAllocatesSequentialIds() {
        Paragraph paragraph = new Paragraph().setWidth(200d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));
        paragraph.add(new Span(font, FONT_SIZE, "B"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        assertEquals(1, resManager.getNewResIds().size(), "相同字体只注册一次");
        assertEquals(Long.valueOf(101L), resManager.getNewResIds().get(0).getId(),
                "字体资源占用第一个ID");

        List<TextObject> texts = textObjects(layer);
        assertEquals(2, texts.size());
        assertEquals(Long.valueOf(102L), texts.get(0).getID().getId(), "首个文字对象使用其后一个ID");
        assertEquals(Long.valueOf(103L), texts.get(1).getID().getId(), "后续文字对象ID依次递增");
        assertEquals(103, maxUnitID.get(), "最大ID应指向最后一个被分配的ID");
    }

    @Test
    @DisplayName("不同字体分别注册资源，文字对象引用各自字体")
    void render_differentFonts_registersBothResources() {
        Font other = uniformWidthFont("OFDRW-Test-Font-2");
        Paragraph paragraph = new Paragraph().setWidth(200d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));
        paragraph.add(new Span(other, FONT_SIZE, "B"));

        ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

        assertEquals(2, resManager.getNewResIds().size(), "两个不同字体应注册两个资源");
        assertEquals(Long.valueOf(101L), resManager.getNewResIds().get(0).getId());
        assertEquals(Long.valueOf(103L), resManager.getNewResIds().get(1).getId());

        List<TextObject> texts = textObjects(layer);
        assertEquals(2, texts.size());
        assertEquals(Long.valueOf(101L), texts.get(0).getFont().getRefId().getId());
        assertEquals(Long.valueOf(103L), texts.get(1).getFont().getRefId().getId());
        assertEquals(Long.valueOf(104L), texts.get(1).getID().getId());
    }

    @Test
    @DisplayName("字体资源加入失败时抛出RenderException并保留原因")
    void render_fontRegistrationFails_throwsRenderException() {
        ResManager failing = new ResManager(ofdDir, docDir, new AtomicInteger(100)) {
            @Override
            public ST_ID addFont(Font font) throws IOException {
                throw new IOException("字体文件不可读");
            }
        };
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));

        RenderException ex = assertThrows(RenderException.class,
                () -> ParagraphRender.render(layer, failing, paragraph, new AtomicInteger(100)));

        assertTrue(ex.getMessage().contains("字体复制失败"), "异常信息应说明字体复制失败：" + ex.getMessage());
        assertTrue(ex.getCause() instanceof IOException, "原始IOException应作为原因保留");
        assertTrue(layer.getPageBlocks().isEmpty(), "渲染异常时不应写入不完整的图元");
    }

    // ------------------------------------------------------------------
    // 辅助方法
    // ------------------------------------------------------------------

    /**
     * 构造一个所有可打印ASCII字符宽度占比均为 1 的字体。
     * <p>
     * 该字体没有字体文件，字符宽度 = 字号 * 占比，因此与系统字体无关，结果确定。
     *
     * @param name 字体名称
     * @return 测试字体
     */
    private static Font uniformWidthFont(String name) {
        double[] map = new double[95];
        for (int i = 0; i < map.length; i++) {
            map[i] = 1.0d;
        }
        return new Font(name, name, null, map);
    }

    /**
     * 渲染只包含一个 "AB" Span 的段落，并返回首字符的X坐标
     *
     * @param align 对齐方式
     * @return 首字符X坐标
     */
    private double renderedTextX(TextAlign align) {
        CT_PageBlock block = new CT_PageBlock();
        Paragraph paragraph = new Paragraph().setWidth(50d);
