@Test
@DisplayName("自动换行时每行渲染一个文字对象，Y坐标按行高递增")
void render_wrappedLines_stackVertically() {
    // 段落宽度 25，每个字符宽度 10，因此每行最多容纳2个字符
    Paragraph paragraph = newParagraph(25d);
    paragraph.add(new Span(font, FONT_SIZE, "AAAAA"));

    ParagraphRender.render(layer, resManager, paragraph, maxUnitID);

    LinkedList<TxtLineBlock> lines = paragraph.getLines();
    assertEquals(3, lines.size(), "5个字符应在宽度25的段落中排为3行");

    List<TextObject> texts = textObjects(layer);
    assertEquals(3, texts.size(), "未限制高度时每行渲染一个文字对象");
    assertEquals("AA", texts.get(0).getTextCodes().get(0).getContent(), "第一行容纳2个字符");
    assertEquals("AA", texts.get(1).getTextCodes().get(0).getContent(), "第二行容纳2个字符");
    assertEquals("A", texts.get(2).getTextCodes().get(0).getContent(), "第三行容纳剩余的1个字符");

    assertEquals(0d, texts.get(0).getBoundary().getTopLeftY(), EPS, "第一行Y为元素Y");
    assertEquals(LINE_HEIGHT, texts.get(1).getBoundary().getTopLeftY(), EPS, "第二行Y增加一个行高");
    assertEquals(2 * LINE_HEIGHT, texts.get(2).getBoundary().getTopLeftY(), EPS, "第三行Y增加两个行高");
    for (TextObject txt : texts) {
        assertEquals(0d, txt.getBoundary().getTopLeftX(), EPS, "每行都从行起始X开始渲染");
    }
    assertEquals(2 * FONT_SIZE, texts.get(0).getBoundary().getWidth(), EPS, "整行文字对象的宽度为行内文字宽度");
    assertEquals(FONT_SIZE, texts.get(2).getBoundary().getWidth(), EPS);
}

