    /**
     * 3页、右侧骑缝、给定 cuttingRatios：
     * 第 i 页使用 cuttingRatios[i].left，回折部分使用 cuttingRatios[i-1].right。
     */
    @Test
    void rightSideHonoursCuttingRatios(@TempDir Path tempDir) throws IOException {
        Path ofd = buildOfd(tempDir, 3, 500d, 200d);
        CountingIDProvider idProvider = new CountingIDProvider();
        List<CuttingRatio> ratios = Arrays.asList(ratio(0.3, 0.7), ratio(0.6, 0.4));
        CuttingRideStampPos pos = new CuttingRideStampPos(Side.Right, null, 100d, 40d, 0d, ratios);

        List<StampAnnot> res;
        try (OFDReader ctx = new OFDReader(ofd)) {
            res = pos.getAppearance(ctx, idProvider);
        }

        assertEquals(4, res.size(), "3页应有 1 + 2 + 1 = 4 个签章外观");
        double y = 80d;

        // 第1页：itemWith = 100 * 0.3 = 30
        assertBoundary(res.get(0), 500d - 30d, y, 100d, 40d);
        assertClip(res.get(0), 0d, 0d, 30d, 40d);
        assertPageRef(res.get(0), pageObjectId(0));

        // 第2页：itemWith = 100 * 0.6 = 60
        assertBoundary(res.get(1), 500d - 60d, y, 100d, 40d);
        assertClip(res.get(1), 0d, 0d, 60d, 40d);
        assertPageRef(res.get(1), pageObjectId(1));

        // 第2页回折：itemWith = 100 * ratios[0].right = 70
        assertBoundary(res.get(2), -(100d - 70d), y, 100d, 40d);
        assertClip(res.get(2), 30d, 0d, 70d, 40d);
        assertPageRef(res.get(2), pageObjectId(1));

        // 第3页（末页）：itemWith = 100 * ratios[1].right = 40
        assertBoundary(res.get(3), -(100d - 40d), y, 100d, 40d);
        assertClip(res.get(3), 60d, 0d, 40d, 40d);
        assertPageRef(res.get(3), pageObjectId(2));

        assertEquals("s004", idProvider.get());
    }

