    @DisplayName("右侧骑缝，未指定偏移与页边距时按总页数均分图章并使图章垂直居中")
    void rightSideWithoutClipSplitsByPageCount() throws IOException {
        OFDReader ctx = reader(new double[]{210, 297}, new double[]{210, 297}, new double[]{210, 297});
        RidingStampPos pos = new RidingStampPos(Side.Right, 30, 20);
        SignIDProvider idProvider = new StandFormatAtomicSignID();

        List<StampAnnot> res = pos.getAppearance(ctx, idProvider);

        assertEquals(3, res.size());
        double itemWidth = 10;
        double centeredY = 297 / 2d - 20 / 2d;
        for (int i = 0; i < 3; i++) {
            StampAnnot annot = res.get(i);
            assertEquals("s00" + (i + 1), annot.getID(), "签名外观ID应依次自增");
            assertEquals(100L + i, annot.getPageRef().getRefId().getId().longValue(), "页面引用应为对应页面对象ID");
            assertBox("第" + (i + 1) + "页外观边界", annot.getBoundary(),
                    210 - itemWidth * (i + 1), centeredY, 30, 20);
            assertBox("第" + (i + 1) + "页裁剪区域", annot.getClip(),
                    itemWidth * i, 0, itemWidth, 20);
        }
    }

