    private OFDReader reader(double[]... pageSizes) throws IOException {
        return readerWithIds(pageSizes, null);
    }

    private OFDReader readerWithIds(double[][] pageSizes, long[] ids) throws IOException {
        Path ofd = dir.resolve("doc-" + (counter++) + ".ofd");
        OFDDir ofdDir = OFDDir.newOFD();
        try {
            DocDir docDir = ofdDir.newDoc();
            PagesDir pagesDir = docDir.obtainPages();
            Pages pages = new Pages();
            for (int i = 0; i < pageSizes.length; i++) {
                double[] size = pageSizes[i];
                PageDir pageDir = pagesDir.newPageDir();
                org.ofdrw.core.basicStructure.pageObj.Page content = new org.ofdrw.core.basicStructure.pageObj.Page();
                content.setArea(new CT_PageArea(0, 0, size[0], size[1]));
                pageDir.setContent(content);
                long id = ids == null ? (100L + i) : ids[i];
                pages.addPage(new org.ofdrw.core.basicStructure.pageTree.Page(id, "Pages/" + pageDir.getContainerName() + "/Content.xml"));
            }
            Document document = new Document();
            document.setCommonData(new CT_CommonData().setPageArea(new CT_PageArea(0, 0, 210, 297)));
            document.setPages(pages);
            docDir.setDocument(document);
            ofdDir.setOfd(new OFD().addDocBody(new DocBody().setDocRoot(new ST_Loc(docDir.getContainerName() + "/Document.xml"))));
            ofdDir.jar(ofd);
        } finally {
            ofdDir.clean();
        }
        OFDReader reader = new OFDReader(ofd);
        readers.add(reader);
        return reader;
    }
